INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(236, 'koKR', 'Paliwo dla niszczycieli', '$n! Najwyższy czas, że się $gzjawiłeś:zjawiłaś;. Bitwa może i się skończyła, ale musimy przygotować się do następnej. Udaj się do Kotła Płomieni w południowo-wschodnim Zimościsku i przynieś trochę wiecznego żaru.$B$BŻar miesza się z węglem i napędza nim niszczyciele i machiny oblężnicze.$B$BA, i jeśli przypadkiem natkniesz się w Kotle na kogoś z Hordy, nie wahaj się go zabić i zabrać mu żar. Nie możemy pozwolić, żeby mieli przewagę w następnej bitwie.', 'Mistrz oblężeń Mocnotrzon z Fortecy Zimościsku chce, żebyś $gzdobył:zdobyła; 10 wiecznych żarów od graczy Hordy w Kotle Płomieni.', '', 'Wróć do mistrza oblężeń Mocnotrzona w Zimościsku.', '', '', '', '', 0),
(13153, 'koKR', 'Ochrona dla wojowników', '$n, dobrze cię widzieć. Bitwa na razie ucichła, ale musimy się pospieszyć i uzupełnić zapasy. Z moich badań wynika, że zbroje żołnierzy niedawno poległych przy Lodowcowych Wodospadach nasycają się ogromną ilością energii. Widziano, jak Horda zbiera tam zbroje.$B$BUdaj się do Lodowcowych Wodospadów i zabij każdego członka Hordy, którego tam spotkasz. Przynieś mi ich nasyconą zbroję.$B$BJeśli nie znajdziesz nikogo z Hordy, może trafisz na zbroję poszukiwacza przygód zabitego przez żywiołaki.', 'Czarodziejka Kaylana z Fortecy Zimościsku chce, żebyś $gzdobył:zdobyła; 10 kompletów nasyconej zbroi Hordy od graczy Hordy przy Lodowcowych Wodospadach.', '', 'Wróć do czarodziejki Kaylany w Zimościsku.', '', '', '', '', 0),
(13154, 'koKR', 'Kości i strzały', 'Smoki są niesamowite! A przynajmniej ich kości! Zaopatruję naszych łuczników w groty ze smoczej kości. Niestety od czasu masakry pod Angrathar zdobycie kości ze Smoczych Pustkowi stało się niemal niemożliwe.$B$BAle w Lesie Cieni na zachodnim skraju Zimościsku jest dość kości, żebyśmy jakoś przetrwali.$B$BIdź do Lasu Cieni i przynieś wszystkie odłamki kości, jakie znajdziesz!$B$BWidziano tam Hordę zbierającą odłamki kości. Zabij ich!', 'Łuczarz Randolph z Fortecy Zimościsku chce, żebyś $gzdobył:zdobyła; 10 kołczanów strzał ze smoczej kości od graczy Hordy w Lesie Cieni.', '', 'Wróć do łuczarza Randolpha w Zimościsku.', '', '', '', '', 0),
(13156, 'koKR', 'Rzadkie zioło', 'Ojej, ale tu chłodno! Przypominają mi się burzowe szczyty Kaarinos na Argusie. Tyle tu śniegu i lodu, że nasi żołnierze łatwo mogą się przeziębić.$B$BUdaj się na Step Życia w południowo-zachodnim Zimościsku i przynieś mi 10 sakiewek na zioła Hordy, które tam znajdziesz. Zmielę je na lek, który pomoże chronić przed zimnem.$B$BWidziano, jak Horda zbiera je z tamtejszych roślin. Nie wahaj się ich zabić i odebrać zioła!', 'Anachoretka Tessa z Fortecy Zimościsku chce, żebyś $gzdobył:zdobyła; 10 sakiewek na zioła Hordy od graczy Hordy na Stepie Życia.', '', 'Wróć do anachoretki Tessy w Zimościsku.', '', '', '', '', 0),
(13177, 'koKR', 'Bez litości dla bezlitosnych', 'Witaj w Fortecy Zimościsku, $n. Twoja misja jest prosta. Pokonaj dziesięciu najlepszych wojowników Hordy. A teraz ruszaj! Przynieś Przymierzu zwycięstwo!', 'Dowódca Zanneth z Fortecy Zimościsku chce, żebyś $gzabił:zabiła; 10 członków Hordy.', '', 'Wróć do dowódcy Zannetha w Zimościsku.', 'Zabici członkowie Hordy', '', '', '', 0),
(13178, 'koKR', 'Zabić ich wszystkich!', 'Witaj w Fortecy Zimościsku, $n. Wódz Garosz żąda tylko jednego: zabić ich wszystkich!$B$BWróć do mnie, gdy zginie dziesięciu najsilniejszych członków Przymierza.', 'Dowódca Dardosh z Fortecy Zimościsku chce, żebyś $gzabił:zabiła; 10 członków Przymierza.', '', 'Wróć do dowódcy Dardosha w Zimościsku.', 'Zabici członkowie Przymierza', '', '', '', 0),
(13179, 'koKR', 'Bez litości dla bezlitosnych', 'Witaj w Zimościsku, $n. Twoja misja jest prosta. Pokonaj dziesięciu najlepszych wojowników Hordy. A teraz ruszaj! Przynieś Przymierzu zwycięstwo!', 'Dowódca Zanneth w Zimościsku chce, żebyś $gzabił:zabiła; 10 członków Hordy.', '', 'Wróć do dowódcy Zannetha w Zimościsku.', 'Zabici członkowie Hordy', '', '', '', 0),
(13180, 'koKR', 'Zabić ich wszystkich!', 'Witaj w Zimościsku, $n. Wódz Garosz żąda tylko jednego: zabić ich wszystkich!$B$BWróć do mnie, gdy zginie dziesięciu najsilniejszych członków Przymierza.', 'Dowódca Dardosh w Zimościsku chce, żebyś $gzabił:zabiła; 10 członków Przymierza.', '', 'Wróć do dowódcy Dardosha w Zimościsku.', 'Zabici członkowie Przymierza', '', '', '', 0),
(13181, 'koKR', 'Zwycięstwo w Zimościsku', 'Dowódcy Zannethowi może wystarczy stos trupów Hordy u stóp, ale dla Ekspedycji Walecznych najważniejsze jest panowanie nad Zimościskiem. Dopilnuj, żeby pozostał w naszych rękach.$B$BI nie myśl sobie, że pozwolimy ci stać z boku, kiedy sojusznicy odwalają za ciebie brudną robotę. Jeśli pod koniec bitwy nie będziesz co najmniej rekrutem drugiego stopnia, nie wracaj.', 'Wygraj bitwę o Zimościsk i wróć do oficera taktycznego Ahbramisa w Zimościsku. Zwycięstwo zostanie ci zaliczone tylko wtedy, gdy weźmiesz udział w bitwie.', 'Zwycięstwo nad Jeziorem Zimościsku', 'Wróć do oficera taktycznego Ahbramisa w Zimościsku.', '', '', '', '', 0),
(13183, 'koKR', 'Zwycięstwo w Zimościsku', 'Dardoshowi może wystarczy zabijanie naszych wrogów, ale najważniejsze jest, byśmy panowali nad Fortecą Zimościsku. Zrób wszystko, co trzeba, żeby Zimościsk był nasz.$B$BI nie myśl sobie, że pozwolimy ci stać z boku, kiedy sojusznicy odwalają za ciebie brudną robotę. Jeśli pod koniec bitwy nie będziesz co najmniej rekrutem drugiego stopnia, nie wracaj.', 'Wygraj bitwę o Zimościsk i wróć do oficera taktycznego Kilratha w Zimościsku. Zwycięstwo zostanie ci zaliczone tylko wtedy, gdy weźmiesz udział w bitwie.', 'Zwycięstwo nad Jeziorem Zimościsku', 'Wróć do oficera taktycznego Kilratha w Zimościsku.', '', '', '', '', 0),
(13185, 'koKR', 'Powstrzymać oblężenie', 'Ja ich słyszeć! Przymierze zaraz przyjść. Zniszcz trzy machiny oblężnicze Przymierza i wróć do Murpa.', 'Porucznik Murp z Fortecy Zimościsku chce, żebyś $gzniszczył:zniszczyła; 3 machiny oblężnicze Przymierza.', '', 'Wróć do porucznika Murpa w Zimościsku.', 'Zniszczone machiny oblężnicze Przymierza', '', '', '', 0),
(13186, 'koKR', 'Powstrzymać oblężenie', 'To tylko kwestia czasu, zanim siły Hordy obiegną ten zamek. Zniszcz trzy ich machiny oblężnicze i wróć do mnie.', 'Starszy saper Legoso z Fortecy Zimościsku chce, żebyś $gzniszczył:zniszczyła; 3 machiny oblężnicze Hordy.', '', 'Wróć do starszego sapera Legoso w Zimościsku.', 'Zniszczone machiny oblężnicze Hordy', '', '', '', 0),
(13191, 'koKR', 'Paliwo dla niszczycieli', 'Lok\'tar, $n! Bitwa może i się skończyła, ale musimy przygotować się na kolejny atak Przymierza! Udaj się do Kotła Płomieni w południowo-wschodnim Zimościsku i przynieś dziesięć wiecznych żarów.$B$BŻar miesza się z węglem i napędza nim niszczyciele i machiny oblężnicze.$B$BDoszły nas słuchy, że świnie z Przymierza cały dzień zbierają tam żar. Zabij ich i zabierz im żar! Jeśli już się stamtąd wynieśli, bądź $ggotów:gotowa; walczyć z tamtejszymi żywiołakami ognia, dopóki go nie zdobędziesz!', 'Kowal oblężniczy Mocne Kopyto z Fortecy Zimościsku chce, żebyś $gzdobył:zdobyła; 10 wiecznych żarów od graczy Przymierza w Kotle Płomieni.', '', 'Wróć do kowala oblężniczego Mocnego Kopyta w Zimościsku.', '', '', '', '', 0),
(13192, 'koKR', 'Osłona dla murów', 'Hej, mon. Od tego miejsca to mnie ciarki przechodzą, wiesz?$B$BZa dużo duchów tu straszy. Ja chcę porozstawiać osłony hoodoo, ale trza mi dusz, mon. I nie byle jakich – tylko dusza silnego wojownika się nada.$B$BLodowcowe Wodospady we wschodnim Zimościsku mają te specjalne właściwości, co wyciągają duszę. Zabij tam Przymierze, może oni mają to, czego nam trza.$B$BPrzynieś zbroję zabitych. A jak nie będzie Przymierza, może żywiołaki ich dorwały, mon.', 'Mistrz hoodoo Fu\'jin z Fortecy Zimościsku chce, żebyś $gzdobył:zdobyła; 10 zaczarowanych napierśników Przymierza przy Lodowcowych Wodospadach.', '', 'Wróć do mistrza hoodoo Fu\'jina w Zimościsku.', '', '', '', '', 0),
(13193, 'koKR', 'Kości i strzały', 'Czemu akurat mnie kazali zbroić naszych łuczników? Byłem poetą, nie tropicielem! No cóż, nie ma co narzekać. $n, potrzebuję smoczej kości na groty strzał.$B$BUdaj się do Lasu Cieni po zachodniej stronie Zimościsku. Od ostatniej potyczki Przymierze wygrzebuje tam smocze kości. Zabij ich i zabierz kości.$B$BA jeśli to się nie uda, przy odrobinie szczęścia zdobędziesz jakąś od tamtejszych duchów. Słyszałem, że uwielbiają nabijać na kości swoje ofiary, póki te jeszcze żyją.', 'Porucznik Vieron Płonące Pióro z Fortecy Zimościsku chce, żebyś $gzdobył:zdobyła; 10 kołczanów strzał ze smoczej kości od graczy Przymierza w Lesie Cieni.', '', 'Wróć do Vierona Płonącego Pióra w Zimościsku.', '', '', '', '', 0),
(13194, 'koKR', 'Leczenie różami', 'Między bitwami można by niemal uwierzyć, że w tej krainie jest nadzieja na pokój. Niestety, nie taki nas czeka los.$B$BUdaj się na Step Życia w południowo-zachodnim Zimościsku. Potrzebuję róż, które tam rosną, na maść do opatrywania rannych.$B$BNiestety róż zrobiło się mało, bo Przymierze zbiera je zbyt łapczywie. Zabij ich na Stepie Życia i zabierz z ciał sakiewki na zioła.$B$BJeśli to się nie uda, może jakiś smagacz czy dwa będzie miał sakiewkę.', 'Prymitywista Mulfort chce, żebyś $gzdobył:zdobyła; 10 sakiewek na zioła Przymierza od graczy Przymierza na Stepie Życia.', '', 'Wróć do prymitywisty Mulforta w Zimościsku.', '', '', '', '', 0),
(13195, 'koKR', 'Rzadkie zioło', 'Ojej, ale tu chłodno! Przypominają mi się burzowe szczyty Kaarinos na Argusie. Tyle tu śniegu i lodu, że nasi żołnierze łatwo mogą się przeziębić.$B$BUdaj się na Step Życia w południowo-zachodnim Zimościsku i przynieś mi 10 sakiewek na zioła Hordy. Zmielę zioła na lek chroniący przed zimnem.$B$BWidziano, jak Horda zbiera je z tamtejszych roślin. Nie wahaj się ich zabić i odebrać zioła!$B$BSakiewkę możesz też znaleźć przy którymś ze smagaczy w okolicy.', 'Anachoretka Tessa w Zimościsku chce, żebyś $gzdobył:zdobyła; 10 sakiewek na zioła Hordy od graczy Hordy na Stepie Życia.', '', 'Wróć do anachoretki Tessy w Zimościsku.', '', '', '', '', 0),
(13196, 'koKR', 'Kości i strzały', 'Smoki są niesamowite! A przynajmniej ich kości! Zaopatruję naszych łuczników w groty ze smoczej kości. Niestety od czasu masakry pod Angrathar zdobycie kości ze Smoczych Pustkowi stało się niemal niemożliwe.$B$BAle w Lesie Cieni na zachodnim skraju Zimościsku jest dość kości, żebyśmy jakoś przetrwali.$B$BIdź do Lasu Cieni i przynieś wszystkie odłamki kości, jakie znajdziesz!$B$BWidziano tam Hordę zbierającą odłamki kości. Zabij ich!', 'Łuczarz Randolph w Zimościsku chce, żebyś $gzdobył:zdobyła; 10 kołczanów strzał ze smoczej kości od graczy Hordy w Lesie Cieni.', '', 'Wróć do łuczarza Randolpha w Zimościsku.', '', '', '', '', 0),
(13197, 'koKR', 'Paliwo dla niszczycieli', '$n! Najwyższy czas, że się $gzjawiłeś:zjawiłaś;. Może i przegraliśmy ostatnią bitwę, ale trzeba się przygotować do następnej! Udaj się do Kotła Płomieni w południowo-wschodnim Zimościsku i przynieś trochę wiecznego żaru.$B$BŻar miesza się z węglem i napędza nim niszczyciele i machiny oblężnicze.$B$BA, i jeśli przypadkiem natkniesz się w Kotle na kogoś z Hordy, nie wahaj się go zabić i zabrać mu żar. Nie możemy dopuścić, żeby utrzymali twierdzę!', 'Mistrz oblężeń Mocnotrzon w Zimościsku chce, żebyś $gzdobył:zdobyła; 10 wiecznych żarów od graczy Hordy w Kotle Płomieni.', '', 'Wróć do mistrza oblężeń Mocnotrzona w Zimościsku.', '', '', '', '', 0),
(13198, 'koKR', 'Ochrona dla wojowników', '$n, dobrze cię widzieć. Musimy się przygotować do kolejnego natarcia na fortecę. Z moich badań wynika, że zbroje żołnierzy niedawno poległych przy Lodowcowych Wodospadach nasycają się ogromną ilością energii. Horda zbiera tam zbroje.$B$BUdaj się do Lodowcowych Wodospadów i zabij każdego członka Hordy, którego tam spotkasz. Przynieś mi ich nasyconą zbroję.$B$BJeśli nie znajdziesz nikogo z Hordy, może trafisz na zbroję poszukiwacza przygód zabitego przez żywiołaki.', 'Czarodziejka Kaylana w Zimościsku chce, żebyś $gzdobył:zdobyła; 10 kompletów nasyconej zbroi Hordy przy Lodowcowych Wodospadach.', '', 'Wróć do czarodziejki Kaylany w Zimościsku.', '', '', '', '', 0),
(13199, 'koKR', 'Kości i strzały', 'Czemu akurat mnie kazali zbroić naszych łuczników? Byłem poetą, nie tropicielem! No cóż, nie ma co narzekać. $n, potrzebuję smoczej kości na groty strzał.$B$BUdaj się do Lasu Cieni po zachodniej stronie Zimościsku. Od ostatniej potyczki Przymierze wygrzebuje tam smocze kości. Zabij ich i zabierz kości.$B$BA jeśli to się nie uda, przy odrobinie szczęścia zdobędziesz jakąś od tamtejszych duchów. Słyszałem, że uwielbiają nabijać na kości swoje ofiary, póki te jeszcze żyją.', 'Porucznik Vieron Płonące Pióro w Zimościsku chce, żebyś $gzdobył:zdobyła; 10 kołczanów strzał ze smoczej kości od graczy Przymierza w Lesie Cieni.', '', 'Wróć do Vierona Płonącego Pióra w Zimościsku.', '', '', '', '', 0),
(13200, 'koKR', 'Paliwo dla niszczycieli', 'Lok\'tar, $n! Bitwa może i ucichła, ale musimy przygotować się do odbicia fortecy! Udaj się do Kotła Płomieni w południowo-wschodnim Zimościsku i przynieś dziesięć wiecznych żarów.$B$BŻar miesza się z węglem i napędza nim niszczyciele i machiny oblężnicze.$B$BDoszły nas słuchy, że świnie z Przymierza cały dzień zbierają tam żar. Zabij ich i zabierz im żar! Jeśli już się stamtąd wynieśli, bądź $ggotów:gotowa; walczyć z tamtejszymi żywiołakami ognia, dopóki go nie zdobędziesz!', 'Kowal oblężniczy Mocne Kopyto w Zimościsku chce, żebyś $gzdobył:zdobyła; 10 wiecznych żarów od graczy Przymierza w Kotle Płomieni.', '', 'Wróć do kowala oblężniczego Mocnego Kopyta w Zimościsku.', '', '', '', '', 0),
(13201, 'koKR', 'Leczenie różami', 'Tylu naszych wojowników padło w bitwie, a zginie jeszcze więcej, jeśli rannych nikt nie opatrzy.$B$BUdaj się na Step Życia w południowo-zachodnim Zimościsku. Potrzebuję róż, które tam rosną, na maść do opatrywania rannych.$B$BNiestety róż zrobiło się mało, bo Przymierze zbiera je zbyt łapczywie. Zabij ich na Stepie Życia i zabierz z ciał sakiewki na zioła.$B$BJeśli to się nie uda, może jakiś smagacz czy dwa akurat zakwitnie.', 'Prymitywista Mulfort w Zimościsku chce, żebyś $gzdobył:zdobyła; 10 sakiewek na zioła Przymierza od graczy Przymierza na Stepie Życia.', '', 'Wróć do prymitywisty Mulforta w Zimościsku.', '', '', '', '', 0),
(13202, 'koKR', 'Klątwa na mury', 'Hej, mon. Widzisz to Przymierze, jak se wygodnie siedzi w swojej twierdzy?$B$BMyślę, że trochę za wygodnie, nie? Ja chcę rzucić na to miejsce klątwę, ale trza mi dusz, mon. I nie byle jakich – tylko dusza silnego wojownika się nada.$B$BLodowcowe Wodospady we wschodnim Zimościsku mają te specjalne właściwości, co wyciągają duszę. Zabij tam Przymierze, oni mają to, czego nam trza.$B$BPrzynieś zbroję zabitych. A jak nie będzie Przymierza, może żywiołaki ich dorwały, mon.', 'Mistrz hoodoo Fu\'jin w Zimościsku chce, żebyś $gzdobył:zdobyła; 10 zaczarowanych napierśników Przymierza od graczy Przymierza przy Lodowcowych Wodospadach.', '', 'Wróć do mistrza hoodoo Fu\'jina w Zimościsku.', '', '', '', '', 0),
(13222, 'koKR', 'Osłona oblężenia', 'Wystąp, $n! Zaczynamy natarcie na Fortecę Zimościsku. Te hordziackie zwierzęta myślą, że mogą tchórzliwie chować się za murami? O nie, nic z tego! Pokażemy im potęgę gnomiej techniki i rozbijemy ich mury w drobny mak!$B$BAle nawet najpotężniejsza machina oblężnicza jest bezradna bez załogi. Pilotuj lub osłaniaj jedną z naszych machin oblężniczych, gdy będzie niszczyć trzy budowle Hordy.', 'Starszy saper Legoso w Zimościsku chce, żebyś $gpilotował:pilotowała; lub $gosłaniał:osłaniała; machinę oblężniczą, gdy będzie niszczyć trzy budowle.$B$BGracze w randze szeregowego lub wyższej mogą budować machiny oblężnicze w goblińskich warsztatach.', '', 'Wróć do starszego sapera Legoso w Zimościsku.', 'Osłonięte machiny oblężnicze', '', '', '', 0),
(13223, 'koKR', 'Osłona oblężenia', 'Przymierze nie utrzymać długo tej twierdzy. Murp by rozwalić mury, ale Murp musieć zostać w obozie. Murp chcieć rozwalić Przymierze, co chce zepsuć niszczyciele Hordy.$B$BTy, $n! Ty iść za Murpa. Chroń 3 machiny oblężnicze, jak one rozwalać budynki Przymierza. Przymierze nie spodziewać się, że ty bronić niszczyciel. Pokaż Przymierzu, jaki Murp sprytny!', 'Porucznik Murp w Zimościsku chce, żebyś $gbronił:broniła; machiny oblężniczej lub ją $gpilotował:pilotowała;, gdy będzie niszczyć trzy budowle Przymierza.$B$BMachiny oblężnicze mogą budować w goblińskich warsztatach gracze Hordy, którzy mają rangę.', '', 'Wróć do porucznika Murpa w Zimościsku.', 'Osłonięte machiny oblężnicze Hordy', '', '', '', 0),
(13538, 'koKR', 'Sabotaż na południu', 'Trzy wieże na południe od Rzeki Zimościsku wysysają moc z fortecy!$B$BZniszcz Wieżę Cienistego Wzroku, Wieżę Płomiennej Straży albo Wieżę Skraju Zimy, a potem wróć do mnie. Pamiętaj, że tylko machiny oblężnicze mogą uszkodzić wieżę, więc osłaniaj je przed Hordą!', 'Zniszcz Wieżę Cienistego Wzroku, Wieżę Płomiennej Straży albo Wieżę Skraju Zimy i wróć do oficera taktycznego Ahbramisa w Zimościsku.', '', 'Wróć do oficera taktycznego Ahbramisa w Zimościsku.', 'Zniszcz jedną z trzech południowych wież', '', '', '', 0),
(13539, 'koKR', 'Obalanie wież', 'Przymierze może i dobija się do naszych bram, ale prawdziwy taktyk patrzy dalej niż na to, co oczywiste.$B$B„Uderzaj tam, gdzie wróg nie jest gotów, zjawiaj się tam, gdzie się ciebie nie spodziewa”.$B$B$n, potrzebuję, żebyś $gprzeprawił:przeprawiła; się przez Rzekę Zimościsku i $gzniszczył:zniszczyła; jedną z trzech wież na południu. Nasi czarnoksiężnicy donoszą, że wieże wysysają moc, którą moglibyśmy wzmocnić własne oddziały.$B$BWróć do mnie, gdy zniszczysz wieżę.', 'Zniszcz Wieżę Cienistego Wzroku, Wieżę Płomiennej Straży albo Wieżę Skraju Zimy i wróć do oficera taktycznego Kilratha w Zimościsku.', '', 'Wróć do oficera taktycznego Kilratha w Zimościsku.', 'Zniszcz południową wieżę w Zimościsku', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(236, 'koKR', 'Doskonale! To podsyci płomienie wojny na długie dni.', 0),
(13153, 'koKR', 'Fuj. Jeszcze z niej kapie. Nie $gmogłeś:mogłaś; jej chociaż najpierw wytrzeć?', 0),
(13154, 'koKR', 'Doskonale! To podsyci płomienie wojny na długie dni.', 0),
(13156, 'koKR', 'Doskonale! To pomoże chronić nasze oddziały przed zimnem.', 0),
(13177, 'koKR', 'Wspaniale! Doprawdy, należysz do czempionów Przymierza.', 0),
(13178, 'koKR', 'Lok\'tar! Zwycięstwo dla Hordy!', 0),
(13179, 'koKR', 'Wspaniale! Doprawdy, należysz do czempionów Przymierza.', 0),
(13180, 'koKR', 'Lok\'tar! Zwycięstwo dla Hordy!', 0),
(13181, 'koKR', 'Właśnie to chciałem usłyszeć! Zwycięstwo nad Jeziorem Zimościsku – nawet tymczasowe – ma kluczowe znaczenie dla całej naszej strategii przeciw Hordzie.', 0),
(13183, 'koKR', '$GDokonałeś:Dokonałaś; dziś naprawdę wielkiej rzeczy. Niech twoje poświęcenie zostanie docenione!', 0),
(13185, 'koKR', 'Dobra robota. Murp chcieć tam być i pomagać.', 0),
(13186, 'koKR', 'Doskonale. To powinno spowolnić ich natarcie.', 0),
(13191, 'koKR', 'Doskonale! To pomoże nam pokonać Przymierze w nadchodzących bitwach!', 0),
(13192, 'koKR', 'Oooch, tak, to jest to, mon!', 0),
(13193, 'koKR', 'No cóż, chyba czeka mnie kolejna noc ostrzenia kości. Czemu nie zostałem w Srebrnej Lunie jak mój brat?', 0),
(13194, 'koKR', 'Dziękuję, to bardzo pomoże w leczeniu ran naszych żołnierzy.', 0),
(13195, 'koKR', 'Doskonale! To pomoże chronić nasze oddziały przed zimnem.', 0),
(13196, 'koKR', 'Doskonale! To podsyci płomienie wojny na długie dni.', 0),
(13197, 'koKR', 'Doskonale! To podsyci płomienie wojny na długie dni.', 0),
(13198, 'koKR', 'Fuj. Jeszcze z niej kapie. Nie $gmogłeś:mogłaś; jej chociaż najpierw wytrzeć?', 0),
(13199, 'koKR', 'No cóż, chyba czeka mnie kolejna noc ostrzenia kości. Czemu nie zostałem w Srebrnej Lunie jak mój brat?', 0),
(13200, 'koKR', 'Doskonale! To powinno nieźle nadszarpnąć ich machiny wojenne!', 0),
(13201, 'koKR', 'Dziękuję, to bardzo pomoże w leczeniu ran naszych żołnierzy.', 0),
(13202, 'koKR', 'Oooch, tak, to jest to, mon!', 0),
(13222, 'koKR', 'To powinno pokazać im potęgę gnomich wynalazków!', 0),
(13223, 'koKR', 'Dobra robota. Murp chcieć tam być i pomagać.', 0),
(13538, 'koKR', 'Słyszałem wybuch aż tutaj! Świetna robota – już zaczęliśmy przekierowywać moc do relikwii tytanów, żeby wzmocnić nasze siły.', 0),
(13539, 'koKR', 'Żeby żołnierze zabijali wroga, trzeba rozpalić w nich gniew; żeby zwycięstwo im się opłacało, muszą dostać nagrodę. Mam nadzieję, że to wystarczy za twoją służbę dla Hordy.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(236, 'koKR', 'No i? Udało ci się znaleźć żar, czy Horda cię uprzedziła i zostawiła $gzapłakanego:zapłakaną;?', 0),
(13153, 'koKR', 'No i? $GZnalazłeś:Znalazłaś; zbroję?', 0),
(13154, 'koKR', 'Jak tam łowy? Słyszałem plotki, że tam straszy, choć sam nigdy się tam nie zapuszczam.', 0),
(13156, 'koKR', 'Mam nadzieję, że nie $gwyrwałeś:wyrwałaś; przez pomyłkę żadnego smagacza! W zeszłym tygodniu porządnie wychłostały szeregowego Doane\'a.', 0),
(13177, 'koKR', 'No i jak, $gwykonałeś:wykonałaś; swoją misję?', 0),
(13178, 'koKR', 'No i jak, $gwykonałeś:wykonałaś; swoją misję?', 0),
(13179, 'koKR', 'No i jak, $gwykonałeś:wykonałaś; swoją misję?', 0),
(13180, 'koKR', 'No i jak, $gwykonałeś:wykonałaś; swoją misję?', 0),
(13181, 'koKR', 'Przynosisz wieści o zwycięstwie?', 0),
(13185, 'koKR', '$GZniszczyłeś:Zniszczyłaś; ich machiny oblężnicze?', 0),
(13186, 'koKR', 'Nie ma czasu do stracenia. $GZniszczyłeś:Zniszczyłaś; ich machiny oblężnicze?', 0),
(13191, 'koKR', 'No i? Udało ci się znaleźć żar, czy Przymierze cię uprzedziło i zostawiło $gzapłakanego:zapłakaną;?', 0),
(13192, 'koKR', 'Masz tę zbroję, mon?', 0),
(13193, 'koKR', 'Już $gwróciłeś:wróciłaś;? A niech to, liczyłem na chwilę odpoczynku.', 0),
(13194, 'koKR', '$GZdołałeś:Zdołałaś; zdobyć zioła? Z każdą godziną przybywa chorych i rannych.', 0),
