(13196, 'koKR', 'Jak tam łowy? Słyszałem plotki, że tam straszy, choć sam nigdy się tam nie zapuszczam.', 0),
(13197, 'koKR', 'No i? Udało ci się znaleźć żar, czy Horda cię uprzedziła i zostawiła $gzapłakanego:zapłakaną;?', 0),
(13198, 'koKR', 'No i? $GZnalazłeś:Znalazłaś; zbroję?', 0),
(13199, 'koKR', 'Już $gwróciłeś:wróciłaś;? A niech to, liczyłem na chwilę odpoczynku.', 0),
(13200, 'koKR', 'No i? Udało ci się znaleźć żar, czy Przymierze cię uprzedziło i zostawiło $gzapłakanego:zapłakaną;?', 0),
(13201, 'koKR', '$GZdołałeś:Zdołałaś; zdobyć zioła? Z każdą godziną przybywa chorych i rannych.', 0),
(13202, 'koKR', 'Masz tę zbroję, mon?', 0),
(13222, 'koKR', 'Nie ma czasu do stracenia. $GZniszczyłeś:Zniszczyłaś; fortecę?', 0),
