INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(3547, 'koKR', '<Wygląda na to, że Archavon prowadził dziennik. Zdaje się, że spisano go w wielu językach. Na okładce ktoś prowadził rachunek. >$B$BHorda:   $B  Twierdza obroniona: $4024w$B  Twierdza zdobyta: $4022w$B$BPrzymierze:$B  Twierdza obroniona: $4025w$B  Twierdza zdobyta: $4023w$B$BDzień 10$BTwórcy odeszli. Zostawili mnie, żebym pilnował.$B                -ARCHAVON$B', 0),
(3548, 'koKR', 'Dzień 10500: $BSale są ciche. Puste. $B$BMyślałem, że Twórcy chcą, żebym pilnował sali, ale nigdy nie powiedzieli wprost: „Archavonie, pilnuj sali”... Może mogę pilnować też na zewnątrz? Na zewnątrz byłoby pewnie mniej nudno. Postanowione – od teraz odpowiadam za pilnowanie sali ORAZ tego, co na zewnątrz. Nowy obowiązek podejmę w przyszłym miesiącu.$B                -ARCHAVON$B$BDzień 20120:$BNa zewnątrz jest dużo więcej miejsca niż w sali. Dookoła są wygodne urwiska i góry. Teraz jestem pewien, że Twórcy chcieli, żebym pilnował i tego. Mam nadzieję, że nie zauważą, że przez pierwsze dziesięć lat siedziałem tylko w sali.$B                -ARCHAVON$B', 0),
(3549, 'koKR', 'Dzień 1051213:$BDziś wymyśliłem też nową grę, nazywa się „Kopnij zjawę”. Dziś dokopałem sprzed twierdzy aż do głównej drogi. Do przyszłego roku spróbuję przerzucić ją za rzekę.$B                -ARCHAVON$B$BDzień 2145617:$BDziś przyszli jacyś mali zieloni ludzie. Dopisałem ich do moich obowiązków pilnowania.$B                -ARCHAVON$B$BDzień 2145657:$BMali zieloni ludzie postawili tu dodatkowe budynki. Więcej budynków to chyba dobrze. Chyba w tym tygodniu z nimi porozmawiam i im podziękuję.$B                -ARCHAVON$B$BDzień 214566:$BPodziękowałem dziś jednemu z małych zielonych ludzi za dodatkowe budynki. Powiedział, że niedługo przyprowadzi mi więcej ludzi do pilnowania – całe mnóstwo.$B$BCieszę się, że będę miał więcej rzeczy do pilnowania.$B                -ARCHAVON$B', 0),
(3602, 'koKR', 'Dzień 214586:$BMali zieloni ludzie przyprowadzili mnóstwo innych, ustawili ich naprzeciw siebie, a potem wszyscy zaczęli walczyć!$B$BDla bezpieczeństwa ograniczyłem swoje obowiązki pilnowania z powrotem do sali, ale zabrałem ze sobą dużo ich błyskotek, żeby tym razem może było mniej nudno.$B                -ARCHAVON$B$BDzień 214620:$BZrobiło się dużo gorzej. Nie wiem, czego chcą ode mnie Twórcy. Staram się siedzieć w swojej sali, ale ci agresywni ludzie przychodzą po mnie kilka razy dziennie. Zabierają mi błyskotki.$B                -ARCHAVON$B$B  ', 0),
(3603, 'koKR', 'Dzień 214701:$BMoi bracia wrócili! Okazało się, że spali w innych zamkniętych salach.$B$BJestem trochę zły, że zostawili mnie samego z całym pilnowaniem, ale i tak podzieliłem się z nimi błyszczącymi błyskotkami, bo mam dość samotności i ciągłych ataków.$B                -ARCHAVON$B$BDzień 214760:$BAgresywni mali ludzie zaczęli atakować moich braci, co jest smutne. Za to mnie teraz przeważnie zostawiają w spokoju, co nie jest smutne.$B$BChyba chcą tych błyszczących błyskotek, które oddałem. Mam wyrzuty sumienia.$B                -ARCHAVON$B', 0);
